import os, psycopg
dsn=os.environ['DATABASE_URL']
sql='''CREATE TABLE IF NOT EXISTS sources(id serial primary key,source_id text unique not null,name text,source_type text,canonical_url text,hostname text,collection_tier text,enabled boolean,created_at timestamptz default now(),updated_at timestamptz default now());CREATE TABLE IF NOT EXISTS news_items(id serial primary key,item_id text unique not null,source_id text references sources(source_id),title text,summary text,canonical_url text unique not null,external_guid text,published_at timestamptz,collected_at timestamptz,language text,adapter_type text,provenance_status text,content_hash text,first_seen_at timestamptz default now(),last_seen_at timestamptz default now(),created_at timestamptz default now(),updated_at timestamptz default now());CREATE TABLE IF NOT EXISTS news_item_provenance(id serial primary key,item_id text unique references news_items(item_id),source_id text references sources(source_id),feed_url text,staging_reference text,checkpoint_reference text,execution_reference text,evidence_status text,evidence_json jsonb,created_at timestamptz default now());CREATE TABLE IF NOT EXISTS import_runs(id serial primary key,run_id text unique not null,started_at timestamptz default now(),completed_at timestamptz,status text,input_item_count int,inserted_count int,updated_count int,unchanged_count int,rejected_count int,input_hash text,error_summary text);CREATE INDEX IF NOT EXISTS news_items_published_idx ON news_items(published_at);CREATE INDEX IF NOT EXISTS news_items_source_idx ON news_items(source_id);'''
with psycopg.connect(dsn) as c: c.execute(sql)
print('migration=ok')
